cat > src/pickList.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { buildPickList, OrderFormatError, type StockLot } from "./pickList";

// Test list:
// [ ] empty text -> empty pick list
// [ ] one order, one item, one lot -> one pick
// [ ] comments and blank lines are ignored
// [ ] no stock -> shortage for the whole quantity
// [ ] partial stock -> pick what is there plus shortage
// [ ] FEFO: earliest expiry first, one pick per lot touched
// [ ] null expiry after dated lots; ties broken by bin
// [ ] stock taken by earlier orders is gone for later ones
// [ ] priority orders are served first, in text order
// [ ] duplicate SKU within an order is summed at first position
// [ ] errors: item before ORDER, duplicate id, empty ORDER, malformed lines
// [ ] the first problem from the top is reported
// [ ] serpentine walking order of picks
// [ ] picks at the same bin keep allocation order
// [ ] stock input is not modified

const lot = (bin: string, sku: string, qty: number, expires: string | null = null): StockLot => ({ bin, sku, qty, expires });

test("format errors name the line", () => {
  const error = new OrderFormatError(7, "quantity must be positive");
  expect(error).toBeInstanceOf(Error);
  expect(error.line).toBe(7);
  expect(error.message).toBe("Line 7: quantity must be positive");
});

test("empty text gives an empty pick list", () => {
  expect(buildPickList("", [])).toEqual({ picks: [], shortages: [] });
});
EOF
bun test 2>&1 | tail -5

cat >> src/pickList.test.ts <<'EOF'

test("one order with one item takes it from the matching lot", () => {
  const result = buildPickList("ORDER 1001\n  OLIVE-500 x3", [lot("A-01-1", "OLIVE-500", 10)]);
  expect(result).toEqual({
    picks: [{ bin: "A-01-1", sku: "OLIVE-500", qty: 3, orderId: "1001" }],
    shortages: [],
  });
});
EOF
